$ErrorActionPreference='Stop'
$r='C:\Users\Fluke\Desktop\Spitfire_USB_Validation';$v='C:\Users\Fluke\Documents\Virtual Machines\Windows XP Professional\Windows XP Professional.vmx'
$active=& 'C:\Program Files\VMware\VMware Workstation\vmrun.exe' list
$vmx=[IO.File]::ReadAllText($v)
$ics=New-Object -ComObject HNetCfg.HNetShare
$sharing=@($ics.EnumEveryConnection | ForEach-Object {$p=$ics.NetConnectionProps($_);$c=$ics.INetSharingConfigurationForINetConnection($_);[pscustomobject]@{name=$p.Name;sharing_enabled=$c.SharingEnabled}})
$result=[ordered]@{utc=[DateTime]::UtcNow.ToString('o');physical_original_accessed=$false;physical_controller_accessed=$false;guest_original_exit_verification=[IO.File]::ReadAllText(($r+'\received\guest-exit-verification--verified-original-exit.txt'));guest_transport_exit=[IO.File]::ReadAllText(($r+'\received\guest-exit-verification-complete.txt'));vm_running=($active -contains $v);vmx_ethernet_lines=@($vmx -split '\r?\n' | Where-Object {$_ -match '^ethernet\d+\.'});vmx_vnc_keys_count=([regex]::Matches($vmx,'(?im)^remoteDisplay\.vnc\.')).Count;vnc_secret_exists=(Test-Path -LiteralPath ($r+'\console-password.tmp'));temporary_tcp_listeners=@(Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | Where-Object {$_.LocalPort -in 5905,18979} | Select LocalAddress,LocalPort);simulator_udp_listeners=@(Get-NetUDPEndpoint -LocalPort 1024 -ErrorAction SilentlyContinue | Where-Object {$_.LocalAddress -eq '10.19.70.13'} | Select LocalAddress,LocalPort);temporary_firewall_rules=@(Get-NetFirewallRule -DisplayName 'Spitfire USB validation hostonly' -ErrorAction SilentlyContinue | Select Name,DisplayName);forwarding=@(Get-NetIPInterface -AddressFamily IPv4 | Select InterfaceAlias,Forwarding);ip_enable_router=(Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters').IPEnableRouter;ics=$sharing;bridge_bindings=@(Get-NetAdapterBinding -ComponentID ms_bridge -ErrorAction SilentlyContinue | Select Name,Enabled);vmnet1_ipv4=@(Get-NetIPAddress -InterfaceAlias 'VMware Network Adapter VMnet1' -AddressFamily IPv4 | Select IPAddress,PrefixLength);fixture_final=(Get-Content -LiteralPath ($r+'\fixture-state.json') -Raw | ConvertFrom-Json);winpcap_installation_retained=$true}
$result | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath ($r+'\validation-cleanup.json') -Encoding UTF8
$result | ConvertTo-Json -Depth 8
if(-not $result.vm_running -or $result.vmx_vnc_keys_count -ne 0 -or $result.vnc_secret_exists -or $result.temporary_tcp_listeners.Count -or $result.simulator_udp_listeners.Count -or $result.temporary_firewall_rules.Count){throw 'Cleanup verification incomplete'}
